package com.quincaisoft.company.application;
import com.quincaisoft.company.api.CompanyBootstrapService;import com.quincaisoft.company.infrastructure.*;import com.quincaisoft.shared.BootstrapScope;import jakarta.persistence.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.*;import java.util.*;import java.time.*;
@Service public class DefaultCompanyBootstrapService implements CompanyBootstrapService { private final EntityManager em; public DefaultCompanyBootstrapService(EntityManager em){this.em=em;}
@Transactional(propagation=Propagation.MANDATORY) public void initialize(BootstrapScope s,String name,String locale) {require(s);var c=new CompanyEntity();c.tenantId=s.tenantId();c.id=s.companyId();c.name=name;c.branchCount=0;em.persist(c);em.flush();var d=new CompanyDefaults();d.tenantId=s.tenantId();d.companyId=s.companyId();d.priceListName="Retail";d.locale=locale;d.fiscalReviewStatus="PROVISIONAL";d.taxConfigurationStatus="REQUIRES_REVIEW";d.currency="XAF";em.persist(d);em.flush();}
private void require(BootstrapScope s) { if(!em.isJoinedToTransaction()) throw new IllegalStateException("Bootstrap must join platform transaction"); Number n=(Number)em.createNativeQuery(BootstrapScope.AUTHORIZATION_SQL).setParameter("p",s.provisioningId()).setParameter("t",s.tenantId()).setParameter("c",s.companyId()).setParameter("b",s.branchId()).setParameter("o",s.ownerId()).getSingleResult(); if(n.longValue()!=1)throw new org.springframework.security.access.AccessDeniedException("Approved current platform bootstrap required"); }
}
